CREATE FUNCTION public.pm_billing_confirm(_items uuid[]) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE p pm_payment_schedule_items;g uuid;project uuid;n integer:=0; BEGIN IF cardinality(_items) IS NULL OR cardinality(_items)<1 THEN RAISE EXCEPTION 'Invoice selection required';END IF; FOR p IN SELECT * FROM pm_payment_schedule_items WHERE id=ANY(_items) ORDER BY id FOR UPDATE LOOP IF n=0 THEN project:=p.project_id;g:=p.manual_billing_group_id;END IF; IF p.project_id<>project OR p.manual_billing_group_id IS DISTINCT FROM g OR public.pm_billing_item_protected(p.id) OR NOT public.can_edit_project_payment_dates(p.project_id) THEN RAISE EXCEPTION 'Forbidden or incompatible selection';END IF;n:=n+1;END LOOP; IF n<>cardinality(_items) OR (g IS NOT NULL AND n<>(SELECT count(*) FROM pm_payment_schedule_items WHERE manual_billing_group_id=g)) THEN RAISE EXCEPTION 'Confirm every member of the group';END IF; FOR p IN SELECT * FROM pm_payment_schedule_items WHERE id=ANY(_items) LOOP PERFORM public.pm_confirm_ready_to_invoice(p.id,'');END LOOP;END $$;
REVOKE ALL ON FUNCTION public.pm_billing_confirm(uuid[]) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.pm_billing_confirm(uuid[]) TO authenticated;